		["🔒 Defeat the lord"] = "🔒 Besiege den Lord",
		["Gold max · gear adds +3"] = "Gold max · Ausrüstung +3",
		["✔ You're wearing your best gear. Tap a slot to compare, or collect set gear in the field"] = "✔ Du trägst deine beste Ausrüstung. Tippe auf einen Platz zum Vergleichen oder sammle Set-Ausrüstung im Feld",
		["Equip it"] = "Ausrüsten",
		["◀ Back to bag"] = "◀ Zurück zur Tasche",
		["⚗ Fuse spare gear into a higher rarity"] = "⚗ Übrige Ausrüstung zu höherer Seltenheit verschmelzen",
		["● ready"] = "● bereit",
		["Spare gear of the same rarity + ✨ Essence → 1 piece of the next rarity. Set, unique and equipped gear are never used."] = "Übrige Ausrüstung gleicher Seltenheit + ✨ Essenz → 1 Teil der nächsten Seltenheit. Set-, Unique- und angelegte Ausrüstung wird nie verwendet.",
